                  style={{ background: BAND_COLOR[b.id] }}
                  aria-hidden="true"
                />
                <span className="text-sm">{b.label}</span>
              </span>
              {b.meaning ? (
                <span className="text-muted-foreground text-sm">{b.meaning}</span>
              ) : null}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

