  const [bx, by] = at(inner - 18);
  const pointer = [
    [tx, ty],
    [bx + 6 * Math.cos(perp), by - 6 * Math.sin(perp)],
    [bx - 6 * Math.cos(perp), by + 6 * Math.sin(perp)],
  ]
    .map((p) => p.map((n) => n.toFixed(1)).join(","))
    .join(" ");
