                              duplicate is theirs and can go. */}
                          {t.source === "user" ? (
                            <>
                              <DropdownMenuSeparator />
                              <DropdownMenuItem onSelect={() => setDeleteTarget({ kind: "template", item: t })}>
                                <Trash2 className="size-4" /> Delete template
                              </DropdownMenuItem>
                            </>
